    15		"github.com/KirkDiggler/rpg-toolkit/tools/spatial"
    16	)
    17	
    18	// SightPayload is the composition-owned encoding of a sighted member's position —
    19	// the payload of every sight-channel intel report. Hosts decode it to render what
    20	// a player sees; intel itself never interprets it.
    21	type SightPayload struct {
    22		Room string  `json:"room"`
    23		X    float64 `json:"x"`
    24		Y    float64 `json:"y"`
    25	}
    26	
    27	// Encounter is the aggregate encounter composition: members, field, clock,
    28	// intel, and record. Construct via NewEncounter; zero value unusable.
    29	// declaredEnding pairs an ending key with its trigger, in Setup order.
    30	type declaredEnding struct {
    31		key     string
    32		trigger Trigger
    33	}
    34	
    35	type Encounter struct {
    36		orchestrator *spatial.BasicRoomOrchestrator
    37		clock        *clock.Tick
    38		intelLog     *intel.Intel
    39		story        *record.Log
    40		members      map[MemberID]*Member
    41		everMembers  map[MemberID]bool // Track all members who have ever joined (for Story access)
    42		deciders     map[MemberID]Decider
    43		// endings holds declared endings in Setup order. Evaluation is
    44		// deterministic (law C8), but NOT globally "first-declared-wins":
    45		// for a single action (Move, Traverse, Join) declaration order is
    46		// the only axis, so the first matching declared ending does win.
    47		// Pump can execute several monsters' actions in one tick, and there
    48		// evaluation walks them in DECISION order first — the action
    49		// decided earliest wins regardless of which of its matching endings
    50		// was declared later; declaration order is only the tiebreak within
    51		// one action's own scan. See Pump's ending-evaluation loop.
    52		endings []declaredEnding
    53		outcome *Outcome
    54		// fieldInput and connectionsInput are stored at Setup time for persistence.
    55		// LoadEncounter uses them to rebuild the field deterministically without
    56		// re-running surveil or requiring an event bus.
    57		fieldInput       []RoomInput
    58		connectionsInput []ConnectionInput
    59	}
    60	
    61	// deepCopyRoomInputs snapshots the caller's room descriptions — the
    62	// persistence source must never alias caller-owned slices (T6 review
    63	// M4: a caller editing its SetupInput after construction silently
    64	// corrupted ToData and made the encounter unsavable).
    65	func deepCopyRoomInputs(rooms []RoomInput) []RoomInput {
    66		out := make([]RoomInput, len(rooms))
    67		for i, r := range rooms {
    68			rc := r
    69			rc.Occluders = append([]spatial.Position(nil), r.Occluders...)
    70			rc.Boundaries = append([]spatial.Boundary(nil), r.Boundaries...)
    71			out[i] = rc
    72		}
    73		return out
    74	}
    75	
    76	// buildRoomGrid constructs the spatial Grid for a room's declared shape.
    77	// Called only after validation has confirmed Grid is one of the three known
    78	// GridShape values; the switch's default (square) is therefore unreachable
    79	// in practice and exists only so an unvalidated caller degrades gracefully
    80	// rather than panicking.
    81	//
    82	// Hex rooms build spatial.AxialHexGrid, NOT spatial.HexGrid: the wire (and
    83	// Platform's pathing) speaks cube coordinates natively, and axial (Q, R,
    84	// with S = -(Q+R) derived) is cube's 2D projection — an IDENTITY mapping to
    85	// the wire. HexGrid's bounded offset column/row coordinates would force a
    86	// lossy, orientation-dependent offset<->cube conversion at that seam for no
    87	// benefit inside the composition, which never renders a grid itself.
    88	// width/height become AxialHexGridConfig's SpanWidth/SpanHeight — see
    89	// RoomInput.Grid's doc comment for what that means for a hex room's
    90	// Position values (origin-centered, negative coordinates legal).
    91	func buildRoomGrid(shape spatial.GridShape, width, height int) spatial.Grid {
    92		switch shape {
    93		case spatial.GridShapeHex:
    94			return spatial.NewAxialHexGrid(spatial.AxialHexGridConfig{SpanWidth: float64(width), SpanHeight: float64(height)})
    95		case spatial.GridShapeGridless:
    96			return spatial.NewGridlessRoom(spatial.GridlessConfig{Width: float64(width), Height: float64(height)})
    97		default:
    98			return spatial.NewSquareGrid(spatial.SquareGridConfig{Width: float64(width), Height: float64(height)})
    99		}
   100	}
   101	
   102	// buildValidRoomGrids rejects room defects before construction (R5
   103	// atomicity — no observable state until Setup succeeds): empty or
   104	// duplicate room ID, and an unrecognized grid shape. On success, returns
   105	// each room's constructed Grid keyed by room ID — reused both for
   106	// downstream bounds checks (connections, and transitively member
   107	// placement via spatial's own PlaceEntity) and later in NewEncounter's
   108	// room-construction loop, so a room's shape is built exactly once and
   109	// every consumer asks the SAME grid. A hardcoded rectangle bounds check
   110	// would silently diverge from GridlessRoom's inclusive upper bound
   111	// (tools/spatial/gridless.go: IsValidPosition uses x <= Width, not
   112	// x < Width like Square/Hex). Reuses ErrNoField — a malformed room list
   113	// is as unusable as an empty one.
   114	func buildValidRoomGrids(rooms []RoomInput) (map[string]spatial.Grid, error) {
   115		seenIDs := make(map[string]bool, len(rooms))
   116		grids := make(map[string]spatial.Grid, len(rooms))
   117		for _, r := range rooms {
   118			if r.ID == "" {
   119				return nil, fmt.Errorf("newencounter: room has empty id: %w", ErrNoField)
   120			}
   121			if seenIDs[r.ID] {
   122				return nil, fmt.Errorf("newencounter: duplicate room %q: %w", r.ID, ErrNoField)
   123			}
   124			seenIDs[r.ID] = true
   125	
   126			switch r.Grid {
   127			case spatial.GridShapeSquare, spatial.GridShapeHex, spatial.GridShapeGridless:
   128			default:
   129				return nil, fmt.Errorf("newencounter: room %q has unknown grid shape %d: %w", r.ID, r.Grid, ErrNoField)
   130			}
   131			grids[r.ID] = buildRoomGrid(r.Grid, r.Width, r.Height)
   132		}
   133		return grids, nil
   134	}
   135	
   136	// validateConnectionInputs rejects connection defects before construction
   137	// (R5 atomicity — no observable state until Setup succeeds): empty or
   138	// duplicate ID, an unknown or self-referencing room, and an endpoint outside
   139	// its room's bounds (per that room's own constructed Grid, from roomGrids —
   140	// see buildValidRoomGrids) or on an occluder position.
   141	func validateConnectionInputs(rooms []RoomInput, roomGrids map[string]spatial.Grid, connections []ConnectionInput) error {
   142		roomsByID := make(map[string]RoomInput, len(rooms))
   143		for _, r := range rooms {
   144			roomsByID[r.ID] = r
   145		}
   146	
   147		seenIDs := make(map[string]bool, len(connections))
   148		for _, c := range connections {
   149			if c.ID == "" {
   150				return fmt.Errorf("newencounter: connection has empty id: %w", ErrBadConnection)
   151			}
   152			if seenIDs[c.ID] {
   153				return fmt.Errorf("newencounter: duplicate connection %q: %w", c.ID, ErrBadConnection)
   154			}
   155			seenIDs[c.ID] = true
   156	
   157			fromRoom, ok := roomsByID[c.From]
   158			if !ok {
   159				return fmt.Errorf("newencounter: connection %q references unknown room %q: %w", c.ID, c.From, ErrBadConnection)
   160			}
   161			toRoom, ok := roomsByID[c.To]
   162			if !ok {
   163				return fmt.Errorf("newencounter: connection %q references unknown room %q: %w", c.ID, c.To, ErrBadConnection)
   164			}
   165			if c.From == c.To {
   166				return fmt.Errorf("newencounter: connection %q connects room %q to itself: %w", c.ID, c.From, ErrBadConnection)
   167			}
   168	
   169			if !roomGrids[c.From].IsValidPosition(c.FromPosition) {
   170				return fmt.Errorf("newencounter: connection %q from-position out of bounds: %w", c.ID, ErrBadConnection)
   171			}
   172			if !roomGrids[c.To].IsValidPosition(c.ToPosition) {
   173				return fmt.Errorf("newencounter: connection %q to-position out of bounds: %w", c.ID, ErrBadConnection)
   174			}
   175	
   176			for _, occ := range fromRoom.Occluders {
   177				if occ.X == c.FromPosition.X && occ.Y == c.FromPosition.Y {
   178					return fmt.Errorf("newencounter: connection %q from-position on occluder: %w", c.ID, ErrBadConnection)
   179				}
   180			}
   181			for _, occ := range toRoom.Occluders {
   182				if occ.X == c.ToPosition.X && occ.Y == c.ToPosition.Y {
   183					return fmt.Errorf("newencounter: connection %q to-position on occluder: %w", c.ID, ErrBadConnection)
   184				}
   185			}
   186		}
   187		return nil
   188	}
   189	
   190	// NewEncounter constructs and initializes an encounter from SetupInput.
   191	// Validation order (first failure wins, R5 atomicity): nil input, no rooms,
   192	// no endings, reserved ending key, empty member ID, duplicate member IDs,
   193	// room defects (empty/duplicate ID, unrecognized grid shape), connection
   194	// defects (empty/duplicate ID, unknown room, self-connection, endpoint out
   195	// of bounds or on an occluder), spatial placement errors.
   196	func NewEncounter(in *SetupInput) (*Encounter, error) {
   197		// Validation order: nil, no rooms, no endings, reserved ending, empty ID, duplicates
   198		if in == nil {
   199			return nil, fmt.Errorf("newencounter: %w", ErrNilInput)
   200		}
   201	
   202		if len(in.Field.Rooms) == 0 {
   203			return nil, fmt.Errorf("newencounter: %w", ErrNoField)
   204		}
   205	
   206		if len(in.Endings) == 0 {
   207			return nil, fmt.Errorf("newencounter: %w", ErrNoEnding)
   208		}
   209	
   210		// Check ending keys
   211		for _, ending := range in.Endings {
   212			if ending.Key == "" || ending.Key == "abandoned" {
   213				return nil, fmt.Errorf("newencounter: %w", ErrNoEnding)
   214			}
   215		}
   216	
   217		// Check member IDs: empty or duplicate; validate deciders
   218		seenIDs := make(map[MemberID]bool)
   219		for _, m := range in.Members {
   220			if m.ID == "" {
   221				return nil, fmt.Errorf("newencounter: %w", ErrNoMember)
   222			}
   223			if seenIDs[m.ID] {
   224				return nil, fmt.Errorf("newencounter: duplicate member %s: %w", m.ID, ErrNoMember)
   225			}
   226			seenIDs[m.ID] = true
   227	
   228			// Players cannot carry deciders (design law C2)
   229			if m.Kind == KindPlayer && m.Decider != nil {
   230				return nil, fmt.Errorf("newencounter: player %s cannot carry a decider: %w", m.ID, ErrNoMember)
   231			}
   232		}
   233	
   234		// Check rooms: unique non-empty IDs, recognized grid shape. roomGrids
   235		// holds each room's constructed Grid, reused below for connection
   236		// bounds validation and again in the room-construction loop so a
   237		// room's shape is built exactly once.
   238		roomGrids, err := buildValidRoomGrids(in.Field.Rooms)
   239		if err != nil {
   240			return nil, err
   241		}
   242	
   243		// Check connections: unique non-empty IDs, endpoints resolve to distinct
   244		// declared rooms, endpoints in bounds (per the room's own grid) and off
   245		// any occluder.
   246		if err = validateConnectionInputs(in.Field.Rooms, roomGrids, in.Field.Connections); err != nil {
   247			return nil, err
   248		}
   249	
   250		// Connections are stored sorted by ID (C8 determinism — order is
   251		// observable in ToData).
   252		connectionsInput := append([]ConnectionInput(nil), in.Field.Connections...)
   253		sort.Slice(connectionsInput, func(i, j int) bool { return connectionsInput[i].ID < connectionsInput[j].ID })
   254	
   255		// After validation passes, construct (R5: no observable state until success)
   256		e := &Encounter{
   257			members:          make(map[MemberID]*Member),
   258			everMembers:      make(map[MemberID]bool),
   259			deciders:         make(map[MemberID]Decider),
   260			endings:          nil,
--- encounter 261-560 ---
   261			fieldInput:       deepCopyRoomInputs(in.Field.Rooms),
   262			connectionsInput: connectionsInput,
   263		}
   264	
   265		// Build clock and intel
   266		e.clock, err = clock.NewTick()
   267		if err != nil {
   268			return nil, fmt.Errorf("newencounter clock: %w", err)
   269		}
   270	
   271		e.intelLog, err = intel.NewIntel()
   272		if err != nil {
   273			return nil, fmt.Errorf("newencounter intel: %w", err)
   274		}
   275	
   276		e.story, err = record.NewLog()
   277		if err != nil {
   278			return nil, fmt.Errorf("newencounter story: %w", err)
   279		}
   280	
   281		// Build field: orchestrator and rooms
   282		e.orchestrator = spatial.NewBasicRoomOrchestrator(spatial.BasicRoomOrchestratorConfig{
   283			ID:     "encounter-orchestrator",
   284			Type:   "orchestrator",
   285			Layout: spatial.LayoutTypeOrganic,
   286		})
   287	
   288		// Create all rooms, reusing each room's already-constructed Grid
   289		// (roomGrids, built above) so validation and placement agree exactly.
   290		roomMap := make(map[string]*spatial.BasicRoom)
   291		for _, ri := range in.Field.Rooms {
   292			room := spatial.NewBasicRoom(spatial.BasicRoomConfig{
   293				ID:   ri.ID,
   294				Type: "room",
   295				Grid: roomGrids[ri.ID],
   296			})
   297			err = e.orchestrator.AddRoom(room)
   298			if err != nil {
   299				return nil, fmt.Errorf("newencounter add room: %w", err)
   300			}
   301			roomMap[ri.ID] = room
   302	
   303			// Add occluders as blocking entities
   304			for _, pos := range ri.Occluders {
   305				occluder := &occluderEntity{id: fmt.Sprintf("occluder-%s-%d-%d", ri.ID, int(pos.X), int(pos.Y))}
   306				_, err = e.orchestrator.PlaceEntity(&spatial.PlaceEntityInput{
   307					RoomID:   spatial.RoomID(ri.ID),
   308					Entity:   occluder,
   309					Position: pos,
   310				})
   311				if err != nil {
   312					return nil, fmt.Errorf("newencounter occluder placement: %w: %w", ErrBadPlacement, err)
   313				}
   314			}
   315	
   316			// Add boundaries
   317			for _, b := range ri.Boundaries {
   318				boundaryRoom := roomMap[ri.ID]
   319				if boundaryRoom != nil {
   320					if br, ok := interface{}(boundaryRoom).(spatial.BoundaryAwareRoom); ok {
   321						err = br.RegisterBoundary(b)
   322						if err != nil {
   323							return nil, fmt.Errorf("newencounter boundary: %w: %w", ErrBadPlacement, err)
   324						}
   325					}
   326				}
   327			}
   328		}
   329	
   330		// Add connections
   331		for _, ci := range in.Field.Connections {
   332			door := spatial.CreateDoorConnection(ci.ID, ci.From, ci.To, 1.0)
   333			err = e.orchestrator.AddConnection(door)
   334			if err != nil {
   335				return nil, fmt.Errorf("newencounter add connection: %w", err)
   336			}
   337		}
   338	
   339		// Place members and collect them
   340		memberIDs := make([]MemberID, 0, len(in.Members))
   341		for _, mi := range in.Members {
   342			memberIDs = append(memberIDs, mi.ID)
   343	
   344			entity := &memberEntity{
   345				id:   string(mi.ID),
   346				kind: mi.Kind,
   347			}
   348	
   349			_, err = e.orchestrator.PlaceEntity(&spatial.PlaceEntityInput{
   350				RoomID:   spatial.RoomID(mi.Room),
   351				Entity:   entity,
   352				Position: mi.Position,
   353			})
   354			if err != nil {
   355				return nil, fmt.Errorf("newencounter member placement: %w: %w", ErrBadPlacement, err)
   356			}
   357	
   358			member := &Member{
   359				ID:   mi.ID,
   360				Kind: mi.Kind,
   361				Room: mi.Room,
   362			}
   363			e.members[mi.ID] = member
   364			e.everMembers[mi.ID] = true // Track in everMembers
   365	
   366			// Store decider if present (monsters only, validated above)
   367			if mi.Decider != nil {
   368				e.deciders[mi.ID] = mi.Decider
   369			}
   370		}
   371	
   372		// Store endings in declaration order (deterministic evaluation, C8)
   373		for _, ei := range in.Endings {
   374			e.endings = append(e.endings, declaredEnding{key: ei.Key, trigger: ei.Trigger})
   375		}
   376	
   377		// First light: build sight percepts for each member using refreshSight
   378		_, err = e.refreshSight(memberIDs)
   379		if err != nil {
   380			return nil, fmt.Errorf("newencounter first light: %w", err)
   381		}
   382	
   383		// Opening record beat: all members hear "scene-opened"
   384		beatPayload, _ := json.Marshal(map[string]string{"beat": "scene-opened"})
   385		_, err = e.story.Append(&record.AppendInput{
   386			At:       0,
   387			Audience: memberIDs,
   388			Tags:     map[string]string{"tag": "scene"},
   389			Payload:  beatPayload,
   390		})
   391		if err != nil {
   392			return nil, fmt.Errorf("newencounter append beat: %w", err)
   393		}
   394	
   395		return e, nil
   396	}
   397	
   398	// View returns the member's current intel holdings.
   399	// Returns ErrNotMember if the member is not part of this encounter.
   400	func (e *Encounter) View(in *ViewInput) ([]intel.Holding, error) {
   401		if in == nil {
   402			return nil, fmt.Errorf("view: %w", ErrNilInput)
   403		}
   404	
   405		if _, ok := e.members[in.Member]; !ok {
   406			return nil, fmt.Errorf("view: %w", ErrNotMember)
   407		}
   408	
   409		holdings, err := e.intelLog.HeldBy(&intel.HeldByInput{Observer: in.Member})
   410		if err != nil {
   411			return nil, fmt.Errorf("view: %w", err)
   412		}
   413	
   414		return holdings, nil
   415	}
   416	
   417	// Members returns the current member roster in stable order.
   418	
   419	// buildMemberOutcomes snapshots every current member's placement in
   420	// sorted-ID order — deterministic output for outcomes and persistence
   421	// (map iteration here was a latent nondeterminism, T6 review M1).
   422	func (e *Encounter) buildMemberOutcomes() []MemberOutcome {
   423		ids := make([]MemberID, 0, len(e.members))
   424		for id := range e.members {
   425			ids = append(ids, id)
   426		}
   427		sort.Slice(ids, func(i, j int) bool { return ids[i] < ids[j] })
   428		outcomes := make([]MemberOutcome, 0, len(ids))
   429		for _, id := range ids {
   430			m := e.members[id]
   431			mRoom, ok := e.orchestrator.GetRoom(m.Room)
   432			if !ok {
   433				continue
   434			}
   435			mPos, ok := mRoom.GetEntityPosition(string(m.ID))
   436			if !ok {
   437				continue
   438			}
   439			outcomes = append(outcomes, MemberOutcome{ID: m.ID, Room: m.Room, Position: mPos})
   440		}
   441		return outcomes
   442	}
   443	
   444	func (e *Encounter) Members() ([]Member, error) {
   445		// Sort by ID for stability
   446		ids := make([]MemberID, 0, len(e.members))
   447		for id := range e.members {
   448			ids = append(ids, id)
   449		}
   450		sort.Slice(ids, func(i, j int) bool {
   451			return ids[i] < ids[j]
   452		})
   453	
   454		members := make([]Member, 0, len(ids))
   455		for _, id := range ids {
   456			members = append(members, *e.members[id])
   457		}
   458		return members, nil
   459	}
   460	
   461	// Status returns the encounter's current state (Open or Closed with Outcome).
   462	// Returns a deep copy of the outcome to prevent aliasing (MUTATION-PROOF).
   463	func (e *Encounter) Status() (*Status, error) {
   464		if e.outcome != nil {
   465			// Deep-copy outcome and its Members slice to prevent aliasing
   466			// (mutation-proof: modifying returned outcome does not affect internal state)
   467			members := make([]MemberOutcome, len(e.outcome.Members))
   468			for i, m := range e.outcome.Members {
   469				members[i] = MemberOutcome{
   470					ID:       m.ID,
   471					Room:     m.Room,
   472					Position: m.Position,
   473				}
   474			}
   475			return &Status{
   476				Open: false,
   477				Outcome: &Outcome{
   478					Ending:  e.outcome.Ending,
   479					At:      e.outcome.At,
   480					Members: members,
   481				},
   482			}, nil
   483		}
   484		return &Status{Open: true}, nil
   485	}
   486	
   487	// Story returns the story entries for a member after the given sequence number.
   488	// Allows both current members and members who have exited (everMembers).
   489	// Returns ErrNilInput if the input is nil, ErrNoMember if the member never joined.
   490	// Copy-out follows record's own conventions (returned entries are already copies
   491	// per record's implementation).
   492	func (e *Encounter) Story(in *StoryInput) ([]record.Entry, error) {
   493		if in == nil {
   494			return nil, fmt.Errorf("story: %w", ErrNilInput)
   495		}
   496	
   497		if _, ok := e.everMembers[in.Audience]; !ok {
   498			return nil, fmt.Errorf("story: %w", ErrNoMember)
   499		}
   500	
   501		entries, err := e.story.SliceFor(&record.SliceForInput{
   502			Viewer:  in.Audience,
   503			FromSeq: in.AfterSeq,
   504		})
   505		if err != nil {
   506			return nil, fmt.Errorf("story: %w", err)
   507		}
   508	
   509		return entries, nil
   510	}
   511	
   512	// moveMember executes a spatial move for a member and returns the old position if successful,
   513	// or an error if the spatial move was rejected. This is the shared managed seam for both
   514	// player moves (Move verb) and monster moves (Pump). The member must exist and be in an
   515	// open encounter; spatial rejection does not abort the operation (handled by caller).
   516	func (e *Encounter) moveMember(member *Member, to spatial.Position) (spatial.Position, error) {
   517		// Get the room and current position
   518		room, ok := e.orchestrator.GetRoom(member.Room)
   519		if !ok {
   520			return spatial.Position{}, fmt.Errorf("movemember: %w", ErrBadPlacement)
   521		}
   522	
   523		currentPos, ok := room.GetEntityPosition(string(member.ID))
   524		if !ok {
   525			return spatial.Position{}, fmt.Errorf("movemember: %w", ErrBadPlacement)
   526		}
   527	
   528		// Attempt the spatial move via managed seam using MoveEntity
   529		_, err := e.orchestrator.MoveEntity(&spatial.MoveEntityInput{
   530			RoomID:   spatial.RoomID(member.Room),
   531			EntityID: core.EntityID(member.ID),
   532			To:       to,
   533		})
   534		if err != nil {
   535			return spatial.Position{}, fmt.Errorf("movemember: %w: %w", ErrBadPlacement, err)
   536		}
   537	
   538		return currentPos, nil
   539	}
   540	
   541	// Move executes a continuous movement within the same room for ANY
   542	// member — players move themselves; Pump routes monster intents through
   543	// the same path. Unfiltered ReachedPosition endings fire only for
   544	// player members; member-filtered endings fire only for the named
   545	// member.
   546	// Validation order (R5 atomicity): nil input → empty member → closed →
   547	// not a member → spatial move rejection. On success, refreshes sight for all members,
   548	// records beat, and evaluates ReachedPosition endings.
   549	func (e *Encounter) Move(in *MoveInput) (*MoveOutput, error) {
   550		// Validation order
   551		if in == nil {
   552			return nil, fmt.Errorf("move: %w", ErrNilInput)
   553		}
   554	
   555		if in.Member == "" {
   556			return nil, fmt.Errorf("move: %w", ErrNoMember)
   557		}
   558	
   559		if e.outcome != nil {
   560			return nil, fmt.Errorf("move: %w", ErrClosed)
--- encounter 561-end ---
   561		}
   562	
   563		member, ok := e.members[in.Member]
   564		if !ok {
   565			return nil, fmt.Errorf("move: %w", ErrNotMember)
   566		}
   567	
   568		// Execute the move through the managed seam
   569		currentPos, err := e.moveMember(member, in.To)
   570		if err != nil {
   571			return nil, fmt.Errorf("move: %w", err)
   572		}
   573	
   574		// Get all member IDs for the refresh scope (v1: refresh everyone)
   575		memberIDs := make([]MemberID, 0, len(e.members))
   576		for id := range e.members {
   577			memberIDs = append(memberIDs, id)
   578		}
   579		sort.Slice(memberIDs, func(i, j int) bool { return memberIDs[i] < memberIDs[j] })
   580	
   581		// Refresh sight for all members
   582		intelDeltas, err := e.refreshSight(memberIDs)
   583		if err != nil {
   584			return nil, fmt.Errorf("move refresh sight: %w", err)
   585		}
   586	
   587		// Record the movement beat
   588		clockReadingInt := e.clock.ToData().HighWater
   589		clockReadingForBeat := uint64(clockReadingInt)
   590		beatPayload := map[string]interface{}{
   591			"beat":     "moved",
   592			"member":   string(in.Member),
   593			"position": in.To,
   594		}
   595		beatBytes, _ := json.Marshal(beatPayload)
   596	
   597		appendOut, err := e.story.Append(&record.AppendInput{
   598			At:       clockReadingForBeat,
   599			Audience: memberIDs,
   600			Tags:     map[string]string{"tag": "movement"},
   601			Payload:  beatBytes,
   602		})
   603		if err != nil {
   604			return nil, fmt.Errorf("move append beat: %w", err)
   605		}
   606	
   607		seqNum := appendOut.Seq
   608	
   609		// Evaluate ReachedPosition endings
   610		var firedOutcome *Outcome
   611		for _, de := range e.endings {
   612			endingKey, trigger := de.key, de.trigger
   613			reachedPosTrigger, ok := trigger.(TriggerReachedPosition)
   614			if !ok {
   615				continue // Not a ReachedPosition trigger
   616			}
   617	
   618			// Check if the ending fires
   619			if reachedPosTrigger.Room != member.Room {
   620				continue // Different room
   621			}
   622	
   623			if reachedPosTrigger.Position.X != in.To.X || reachedPosTrigger.Position.Y != in.To.Y {
   624				continue // Different position
   625			}
   626	
   627			// Check member filter: empty = any player member; non-empty = specific member
   628			if reachedPosTrigger.Member != "" && reachedPosTrigger.Member != in.Member {
   629				continue // Member filter doesn't match
   630			}
   631	
   632			// Member filter passes (empty or matches) but we need to check kind
   633			if reachedPosTrigger.Member == "" && member.Kind != KindPlayer {
   634				continue // Empty filter means players only, but moved member is not player
   635			}
   636	
   637			// Ending fires! Build the outcome with all members' current positions
   638			memberOutcomes := e.buildMemberOutcomes()
   639	
   640			e.outcome = &Outcome{
   641				Ending:  endingKey,
   642				At:      clockReadingForBeat,
   643				Members: memberOutcomes,
   644			}
   645			// Return a deep copy of the outcome (mutation-proof)
   646			outcomeMembers := make([]MemberOutcome, len(e.outcome.Members))
   647			for i, m := range e.outcome.Members {
   648				outcomeMembers[i] = MemberOutcome{
   649					ID:       m.ID,
   650					Room:     m.Room,
   651					Position: m.Position,
   652				}
   653			}
   654			firedOutcome = &Outcome{
   655				Ending:  e.outcome.Ending,
   656				At:      e.outcome.At,
   657				Members: outcomeMembers,
   658			}
   659			break
   660		}
   661	
   662		return &MoveOutput{
   663			Moved: struct {
   664				Member MemberID
   665				From   spatial.Position
   666				To     spatial.Position
   667			}{
   668				Member: in.Member,
   669				From:   currentPos,
   670				To:     in.To,
   671			},
   672			IntelDeltas: intelDeltas,
   673			Seq:         seqNum,
   674			Outcome:     firedOutcome,
   675		}, nil
   676	}
   677	
   678	// traverseResult holds the outcome of a successful cross-room move via
   679	// traverseMember — shared by the Traverse verb and Pump's IntentTraverse
   680	// executor.
   681	type traverseResult struct {
   682		fromRoom string
   683		fromPos  spatial.Position
   684		toRoom   string
   685		toPos    spatial.Position
   686	}
   687	
   688	// traverseMember resolves connectionID against this encounter's declared
   689	// connections, determines direction from member's CURRENT room/position
   690	// (they must be standing exactly on one of the connection's two
   691	// endpoints — connections are bidirectional, T1 law), and moves the
   692	// entity between rooms via spatial's TransitionEntity + PlaceEntity
   693	// managed seams, mutating member.Room on success. ANY failure (unknown
   694	// connection, endpoint mismatch, or a spatial rejection) returns before
   695	// member.Room is touched.
   696	//
   697	// Shared by the Traverse verb (which owns the nil/closed/member-lookup
   698	// guards and propagates this function's error as its own public
   699	// contract — ErrNoConnection or ErrBadPlacement, already correctly
   700	// wrapped here) and Pump's phase-2 IntentTraverse executor (which owns
   701	// Pump's silent-skip-on-failure semantics: ANY error returned here is
   702	// treated exactly like a spatially-rejected IntentMoveTo — the monster
   703	// simply fails to act this tick, no abort).
   704	func (e *Encounter) traverseMember(member *Member, connectionID string) (traverseResult, error) {
   705		var conn *ConnectionInput
   706		for i := range e.connectionsInput {
   707			if e.connectionsInput[i].ID == connectionID {
   708				conn = &e.connectionsInput[i]
   709				break
   710			}
   711		}
   712		if conn == nil {
   713			return traverseResult{}, fmt.Errorf("connection %s not found: %w", connectionID, ErrNoConnection)
   714		}
   715	
   716		room, ok := e.orchestrator.GetRoom(member.Room)
   717		if !ok {
   718			return traverseResult{}, fmt.Errorf("%w", ErrBadPlacement)
   719		}
   720		fromPos, ok := room.GetEntityPosition(string(member.ID))
   721		if !ok {
   722			return traverseResult{}, fmt.Errorf("%w", ErrBadPlacement)
   723		}
   724		fromRoom := member.Room
   725	
   726		// The member must be standing exactly on one of the connection's two
   727		// endpoints. Determine direction from WHICH endpoint they're on — the
   728		// arrival side is always the connection's OTHER endpoint (never the
   729		// one the member is currently standing on).
   730		var toRoom string
   731		var toPos spatial.Position
   732		switch {
   733		case fromRoom == conn.From && fromPos.X == conn.FromPosition.X && fromPos.Y == conn.FromPosition.Y:
   734			toRoom, toPos = conn.To, conn.ToPosition
   735		case fromRoom == conn.To && fromPos.X == conn.ToPosition.X && fromPos.Y == conn.ToPosition.Y:
   736			toRoom, toPos = conn.From, conn.FromPosition
   737		default:
   738			return traverseResult{}, fmt.Errorf("member %s is not at connection %s's endpoint: %w", member.ID, connectionID, ErrBadPlacement)
   739		}
   740	
   741		// Move the entity between rooms via spatial's purpose-built transition
   742		// seam: TransitionEntity removes from the source room (the SAME
   743		// registry cleanup RemoveEntity performs — the wave-1 Exit lesson
   744		// applies here too) and, as a backstop behind our own checks above,
   745		// independently re-validates against spatial's own bookkeeping that
   746		// the connection exists, actually links these two rooms (in either
   747		// direction, since door connections are Reversible), and the entity
   748		// was truly indexed in the departure room. TransitionEntity
   749		// deliberately does NOT place the entity — PlaceEntity must always
   750		// follow, using the SAME entity value TransitionEntity returned.
   751		transitioned, err := e.orchestrator.TransitionEntity(&spatial.TransitionEntityInput{
   752			EntityID:     core.EntityID(member.ID),
   753			FromRoom:     spatial.RoomID(fromRoom),
   754			ToRoom:       spatial.RoomID(toRoom),
   755			ConnectionID: spatial.ConnectionID(connectionID),
   756		})
   757		if err != nil {
   758			return traverseResult{}, fmt.Errorf("transition entity: %w: %w", ErrBadPlacement, err)
   759		}
   760

