   286	// AxialHexGrid implements an origin-centered hex grid whose Position values
   287	// are axial coordinates: Position.X = Q, Position.Y = R, S = -(Q+R).
   288	// It is intentionally distinct from HexGrid, which interprets the same fields
   289	// as bounded offset column/row coordinates and supports orientation selection.
   290	//
   291	// Distance uses the cube formula: (|ΔQ| + |ΔR| + |ΔS|) / 2, so adjacent
   292	// hexes are distance 1 in every axial direction.
   293	type AxialHexGrid struct {
   294		dimensions Dimensions
   295	}
   296	
   297	// AxialHexGridConfig holds configuration for creating an AxialHexGrid.
   298	// SpanWidth and SpanHeight define the total span of valid axial coordinates.
   299	// IsValidPosition checks are centered on the origin — a position (Q, R) is
   300	// valid when Q ∈ [-SpanWidth/2, SpanWidth/2) and R ∈ [-SpanHeight/2,
   301	// SpanHeight/2). This differs from SquareGrid/HexGrid, whose Width/Height
   302	// are one-sided bounds starting at (0,0). Pass large values (e.g. 1000×1000)
   303	// for encounter rooms where position bounds are not meaningful.
   304	type AxialHexGridConfig struct {
   305		SpanWidth  float64
   306		SpanHeight float64
   307	}
   308	
   309	// NewAxialHexGrid creates a new hex grid that treats Position.X/Y as axial
   310	// Q/R coordinates. Use this instead of NewHexGrid when positions are stored
   311	// in axial (not offset) form.
   312	func NewAxialHexGrid(config AxialHexGridConfig) *AxialHexGrid {
   313		return &AxialHexGrid{
   314			dimensions: Dimensions{Width: config.SpanWidth, Height: config.SpanHeight},
   315		}
   316	}
