   347	// GetNeighbors returns the 6 axial positions adjacent to pos.
   348	func (a *AxialHexGrid) GetNeighbors(pos Position) []Position {
   349		cube := axialToCube(pos)
   350		neighborCubes := cube.GetNeighbors()
   351		neighbors := make([]Position, 0, 6)
   352		for _, nc := range neighborCubes {
   353			np := cubeToAxial(nc)
   354			if a.IsValidPosition(np) {
   355				neighbors = append(neighbors, np)
   356			}
   357		}
   358		return neighbors
   359	}
