   361	// IsAdjacent reports whether two positions are adjacent (hex distance <= 1).
   362	func (a *AxialHexGrid) IsAdjacent(pos1, pos2 Position) bool {
   363		return a.Distance(pos1, pos2) <= 1
   364	}
