   366	// GetLineOfSight returns hex positions along the line from from to to using
   367	// cube-coordinate linear interpolation (standard hex line algorithm).
   368	func (a *AxialHexGrid) GetLineOfSight(from, to Position) []Position {
   369		if from.Equals(to) {
   370			return []Position{from}
   371		}
   372		fromCube := axialToCube(from)
   373		toCube := axialToCube(to)
   374		dist := fromCube.Distance(toCube)
   375		if dist == 0 {
   376			// from != to (the Equals check above only catches exact float
   377			// equality) but both truncate to the same cube cell -- e.g.
   378			// fractional positions in the same hex. t := i/dist below would be
   379			// 0/0 (NaN) otherwise.
   380			return []Position{from}
   381		}
   382		positions := make([]Position, 0, dist+1)
   383		for i := 0; i <= dist; i++ {
   384			t := float64(i) / float64(dist)
   385			lerped := lerpCube(fromCube, toCube, t)
   386			rounded := roundCube(lerped)
   387			pos := cubeToAxial(rounded)
   388			if a.IsValidPosition(pos) {
   389				positions = append(positions, pos)
   390			}
   391		}
   392		return positions
   393	}
