   395	// GetPositionsInRange returns all valid axial positions within radius hex
   396	// steps of center.
   397	func (a *AxialHexGrid) GetPositionsInRange(center Position, radius float64) []Position {
   398		centerCube := axialToCube(center)
   399		iRadius := int(radius)
   400		positions := make([]Position, 0)
   401		for dq := -iRadius; dq <= iRadius; dq++ {
   402			rMin := intMax(-iRadius, -dq-iRadius)
   403			rMax := intMin(iRadius, -dq+iRadius)
   404			for dr := rMin; dr <= rMax; dr++ {
   405				ds := -dq - dr
   406				candidate := CubeCoordinate{X: centerCube.X + dq, Y: centerCube.Y + dr, Z: centerCube.Z + ds}
   407				pos := cubeToAxial(candidate)
   408				if a.IsValidPosition(pos) {
   409					positions = append(positions, pos)
   410				}
   411			}
   412		}
   413		return positions
   414	}
