   420		minQ := rect.Position.X
   421		maxQ := rect.Position.X + rect.Dimensions.Width - 1
   422		minR := rect.Position.Y
   423		maxR := rect.Position.Y + rect.Dimensions.Height - 1
   424		for q := minQ; q <= maxQ; q++ {
