   445	// GetPositionsInCone returns axial positions within a cone.
   446	func (a *AxialHexGrid) GetPositionsInCone(origin, direction Position, length, angle float64) []Position {
   447		dirLength := math.Sqrt(direction.X*direction.X + direction.Y*direction.Y)
   448		if dirLength == 0 {
   449			return []Position{}
   450		}
   451		dirX := direction.X / dirLength
   452		dirY := direction.Y / dirLength
   453		candidates := a.GetPositionsInRange(origin, length)
   454		positions := make([]Position, 0, len(candidates))
   455		for _, pos := range candidates {
   456			if pos.Equals(origin) {
   457				positions = append(positions, pos)
   458				continue
   459			}
   460			posX := pos.X - origin.X
   461			posY := pos.Y - origin.Y
   462			posLen := math.Sqrt(posX*posX + posY*posY)
   463			if posLen == 0 {
   464				continue
   465			}
   466			dot := (dirX*posX + dirY*posY) / posLen
   467			if math.Acos(math.Max(-1, math.Min(1, dot))) <= angle/2 {
   468				positions = append(positions, pos)
   469			}
   470		}
   471		return positions
   472	}
