   474	// axialToCube converts an axial Position (X=Q, Y=R) to a CubeCoordinate.
   475	func axialToCube(pos Position) CubeCoordinate {
   476		q := int(pos.X)
   477		r := int(pos.Y)
   478		return CubeCoordinate{X: q, Y: r, Z: -q - r}
   479	}
   480	
   481	// cubeToAxial converts a CubeCoordinate back to an axial Position (X=Q, Y=R).
   482	func cubeToAxial(c CubeCoordinate) Position {
   483		return Position{X: float64(c.X), Y: float64(c.Y)}
   484	}
   485	
   486	// lerpCube linearly interpolates between two CubeCoordinates. Uses float
   487	// arithmetic before rounding (via roundCube) so the cube invariant is
   488	// preserved — see rpg-toolkit#788, where HexGrid used to truncate here
   489	// with int() instead, producing a path-direction-dependent (asymmetric)
   490	// line at distance >= 22 hexes.
   491	func lerpCube(from, to CubeCoordinate, t float64) cubeFloat {
   492		return cubeFloat{
   493			x: float64(from.X) + t*float64(to.X-from.X),
   494			y: float64(from.Y) + t*float64(to.Y-from.Y),
   495			z: float64(from.Z) + t*float64(to.Z-from.Z),
   496		}
   497	}
   498	
   499	// cubeFloat is a floating-point cube coordinate used only during line
   500	// interpolation to avoid premature integer truncation.
   501	type cubeFloat struct{ x, y, z float64 }
   502	
   503	// roundCube rounds a floating-point cube to the nearest valid hex,
   504	// preserving the cube constraint x+y+z=0.
   505	func roundCube(c cubeFloat) CubeCoordinate {
   506		rx := math.Round(c.x)
   507		ry := math.Round(c.y)
   508		rz := math.Round(c.z)
   509		xDiff := math.Abs(rx - c.x)
   510		yDiff := math.Abs(ry - c.y)
   511		zDiff := math.Abs(rz - c.z)
   512		switch {
   513		case xDiff > yDiff && xDiff > zDiff:
   514			rx = -ry - rz
   515		case yDiff >= zDiff:
   516			ry = -rx - rz
   517		default:
   518			rz = -rx - ry
   519		}
   520		return CubeCoordinate{X: int(rx), Y: int(ry), Z: int(rz)}
