   115	
   116	// IsValid checks whether the cube coordinate is valid (x + y + z == 0).
   117	// It compares exact unsigned magnitudes by sign instead of adding native ints,
   118	// so valid and invalid coordinates remain distinguishable at int extremes.
   119	func (c CubeCoordinate) IsValid() bool {
   120		var positive, negative uint
   121		for _, value := range [...]int{c.X, c.Y, c.Z} {
   122			if value > 0 {
   123				magnitude := uint(value)
   124				if positive > ^uint(0)-magnitude {
   125					return false
   126				}
   127				positive += magnitude
   128				continue
   129			}
   130			if value < 0 {
   131				// -(MinInt) cannot be represented as an int. Subtract one before
   132				// negating, then restore that unsigned unit exactly.
   133				//nolint:gosec // G115: value < 0, so -(value+1) is representable and non-negative.
   134				magnitude := uint(-(value + 1)) + 1
   135				if negative > ^uint(0)-magnitude {
   136					return false
   137				}
   138				negative += magnitude
   139			}
   140		}
   141		return positive == negative
   142	}
