   197	// ToOffsetCoordinateWithOrientation converts cube coordinate to offset coordinate
   198	// using the specified hex orientation
   199	func (c CubeCoordinate) ToOffsetCoordinateWithOrientation(orientation HexOrientation) Position {
   200		switch orientation {
   201		case HexOrientationFlatTop:
   202			// Flat-top: odd-r offset coordinates
   203			col := float64(c.X + (c.Z-(c.Z&1))/2)
   204			row := float64(c.Z)
   205			return Position{X: col, Y: row}
   206		default:
   207			// Pointy-top: odd-q offset coordinates (default)
   208			col := float64(c.X)
