   503	// roundCube rounds a floating-point cube to the nearest valid hex,
   504	// preserving the cube constraint x+y+z=0.
   505	func roundCube(c cubeFloat) CubeCoordinate {
   506		rx := math.Round(c.x)
   507		ry := math.Round(c.y)
   508		rz := math.Round(c.z)
   509		xDiff := math.Abs(rx - c.x)
   510		yDiff := math.Abs(ry - c.y)
   511		zDiff := math.Abs(rz - c.z)
   512		switch {
   513		case xDiff > yDiff && xDiff > zDiff:
   514			rx = -ry - rz
   515		case yDiff >= zDiff:
   516			ry = -rx - rz
   517		default:
   518			rz = -rx - ry
   519		}
   520		return CubeCoordinate{X: int(rx), Y: int(ry), Z: int(rz)}
