   198	// using the specified hex orientation
   199	func (c CubeCoordinate) ToOffsetCoordinateWithOrientation(orientation HexOrientation) Position {
   200		switch orientation {
   201		case HexOrientationFlatTop:
   202			// Flat-top: odd-r offset coordinates
   203			col := float64(c.X + (c.Z-(c.Z&1))/2)
   204			row := float64(c.Z)
   205			return Position{X: col, Y: row}
   206		default:
   207			// Pointy-top: odd-q offset coordinates (default)
   208			col := float64(c.X)
   209			row := float64(c.Z + (c.X-(c.X&1))/2)
   210			return Position{X: col, Y: row}
   211		}
   212	}
   213	
   214	// OffsetCoordinateToCube converts offset coordinate to cube coordinate
   215	// Uses pointy-top orientation by default. Use OffsetCoordinateToCubeWithOrientation for flat-top.
   216	func OffsetCoordinateToCube(pos Position) CubeCoordinate {
   217		return OffsetCoordinateToCubeWithOrientation(pos, HexOrientationPointyTop)
   218	}
   219	
   220	// OffsetCoordinateToCubeWithOrientation converts offset coordinate to cube coordinate
   221	// using the specified hex orientation
   222	func OffsetCoordinateToCubeWithOrientation(pos Position, orientation HexOrientation) CubeCoordinate {
   223		col := int(pos.X)
   224		row := int(pos.Y)
   225	
   226		switch orientation {
   227		case HexOrientationFlatTop:
   228			// Flat-top: odd-r offset coordinates
   229			x := col - (row-(row&1))/2
   230			z := row
   231			y := -x - z
   232			return CubeCoordinate{X: x, Y: y, Z: z}
   233		default:
   234			// Pointy-top: odd-q offset coordinates (default)
   235			x := col
   236			z := row - (col-(col&1))/2
   237			y := -x - z
   238			return CubeCoordinate{X: x, Y: y, Z: z}
   239		}
   240	}
