   242	// Rectangle represents a rectangular area
   243	type Rectangle struct {
   244		Position   Position   `json:"position"`
   245		Dimensions Dimensions `json:"dimensions"`
   246	}
   247	
   248	// String returns a string representation of the rectangle
   249	func (r Rectangle) String() string {
   250		return fmt.Sprintf("Rect[%s %s]", r.Position, r.Dimensions)
   251	}
   252	
   253	// Contains checks if a position is within the rectangle
   254	func (r Rectangle) Contains(pos Position) bool {
   255		return pos.X >= r.Position.X && pos.X < r.Position.X+r.Dimensions.Width &&
   256			pos.Y >= r.Position.Y && pos.Y < r.Position.Y+r.Dimensions.Height
   257	}
   258	
   259	// Center returns the center position of the rectangle
   260	func (r Rectangle) Center() Position {
   261		return Position{
   262			X: r.Position.X + r.Dimensions.Width/2,
   263			Y: r.Position.Y + r.Dimensions.Height/2,
   264		}
   265	}
   266	
   267	// Intersects checks if this rectangle intersects with another rectangle
   268	func (r Rectangle) Intersects(other Rectangle) bool {
   269		return r.Position.X < other.Position.X+other.Dimensions.Width &&
   270			r.Position.X+r.Dimensions.Width > other.Position.X &&
   271			r.Position.Y < other.Position.Y+other.Dimensions.Height &&
   272			r.Position.Y+r.Dimensions.Height > other.Position.Y
   273	}
