   286	// Contains checks if a position is within the circle
   287	func (c Circle) Contains(pos Position) bool {
   288		// Note: This uses Euclidean distance - actual distance rules depend on grid type
   289		dx := c.Center.X - pos.X
   290		dy := c.Center.Y - pos.Y
   291		return math.Sqrt(dx*dx+dy*dy) <= c.Radius
   292	}
