   295	func (c Circle) Intersects(other Circle) bool {
   296		// Note: This uses Euclidean distance - actual distance rules depend on grid type
   297		dx := c.Center.X - other.Center.X
   298		dy := c.Center.Y - other.Center.Y
   299		return math.Sqrt(dx*dx+dy*dy) <= c.Radius+other.Radius
   300	}
