    80	// SurveilInput carries a complete percept for this observer+channel.
    81	type SurveilInput struct {
    82		Observer core.EntityID
    83		Channel  Channel
    84		Percept  []Report
    85		At       uint64
    86	}
    87	
    88	// SurveilOutput reports the deltas Surveil caused.
    89	type SurveilOutput struct {
    90		FirstContact []Report
    91		Refreshed    []Subject
    92		Faded        []Subject
    93	}
    94	
    95	// ReportInput is the input to the Report verb.
    96	type ReportInput struct {
    97		Observer core.EntityID
    98		Channel  Channel
    99		Reports  []Report
   100		At       uint64
   101	}
   102	
   103	// Surveil records a complete percept for an observer+channel. Fading is
   104	// derived: every subject previously current via this channel but absent from
   105	// Percept has that channel removed from CurrentVia. If CurrentVia becomes
   106	// empty, the subject fades (still held — the ghost goblin). An empty Percept
   107	// is legal (seeing nothing: fades everything this channel sustained). Errors:
   108	// ErrNilInput, ErrNoObserver, ErrNoChannel, ErrNoSubject — validation first,
   109	// all before any mutation (R5).
   110	func (i *Intel) Surveil(in *SurveilInput) (*SurveilOutput, error) {
   111		if in == nil {
   112			return nil, fmt.Errorf("surveil: %w", ErrNilInput)
   113		}
   114	
   115		if in.Observer == "" {
   116			return nil, fmt.Errorf("surveil: %w", ErrNoObserver)
   117		}
   118	
   119		if in.Channel == "" {
   120			return nil, fmt.Errorf("surveil: %w", ErrNoChannel)
   121		}
   122	
   123		for _, report := range in.Percept {
   124			if report.Subject == "" {
   125				return nil, fmt.Errorf("surveil: %w", ErrNoSubject)
   126			}
   127		}
   128	
   129		// Dedupe percept (same as Report): last entry wins, survivor at last position
   130		deduped := dedupeReports(in.Percept)
   131		dedupeSubjectSet := make(map[Subject]struct{}, len(deduped))
   132		for _, r := range deduped {
   133			dedupeSubjectSet[r.Subject] = struct{}{}
   134		}
   135	
   136		out := &SurveilOutput{}
   137	
   138		// Phantom-observer guard: lazy observer-map creation only after validation
   139		// and only if the deduped percept is non-empty OR observer already exists
   140		if len(deduped) == 0 && i.holdings[in.Observer] == nil {
   141			// Empty percept for unknown observer must not create state
   142			return out, nil
   143		}
   144	
   145		// Ensure observer exists if we're about to do something
   146		if i.holdings[in.Observer] == nil {
   147			i.holdings[in.Observer] = make(map[Subject]*holding)
   148		}
   149	
   150		// FADE PASS: from pre-mutation state, remove channel from holdings
   151		// whose currentVia contains this channel AND subject absent from deduped percept
   152		var fadedSubjects []Subject
   153		for subj, h := range i.holdings[in.Observer] {
   154			// Check if this subject was sustained by this channel
   155			if _, ok := h.currentVia[in.Channel]; ok {
   156				// Check if it's absent from the deduped percept
   157				if _, present := dedupeSubjectSet[subj]; !present {
   158					// Remove the channel
   159					delete(h.currentVia, in.Channel)
   160					// If currentVia is now empty, collect for Faded
   161					if len(h.currentVia) == 0 {
   162						fadedSubjects = append(fadedSubjects, subj)
   163					}
   164				}
   165			}
   166		}
   167	
   168		// Sort Faded by Subject for deterministic transcripts; only assign if non-empty
   169		if len(fadedSubjects) > 0 {
   170			slices.SortFunc(fadedSubjects, func(a, b Subject) int {
   171				if a < b {
   172					return -1
   173				}
   174				if a > b {
   175					return 1
   176				}
   177				return 0
   178			})
   179			out.Faded = fadedSubjects
   180		}
   181	
   182		// LAND PASS: in post-dedupe percept order
   183		for _, report := range deduped {
   184			h, exists := i.holdings[in.Observer][report.Subject]
   185			if !exists {
   186				// Unknown subject: create holding with independent payload copy
   187				payloadCopy := make([]byte, len(report.Payload))
   188				copy(payloadCopy, report.Payload)
   189				i.holdings[in.Observer][report.Subject] = &holding{
   190					payload:    payloadCopy,
   191					channel:    in.Channel,
   192					at:         in.At,
   193					currentVia: map[Channel]struct{}{in.Channel: {}},
   194				}
   195				// Return independent copy for FirstContact
   196				fcPayload := make([]byte, len(report.Payload))
   197				copy(fcPayload, report.Payload)
   198				out.FirstContact = append(out.FirstContact, Report{
   199					Subject: report.Subject,
   200					Payload: fcPayload,
   201				})
   202			} else {
   203				// Known: overwrite payload (copy), channel, at, and add channel to currentVia
   204				payloadCopy := make([]byte, len(report.Payload))
   205				copy(payloadCopy, report.Payload)
   206				h.payload = payloadCopy
   207				h.channel = in.Channel
   208				h.at = in.At
   209				h.currentVia[in.Channel] = struct{}{}
   210				out.Refreshed = append(out.Refreshed, report.Subject)
   211			}
   212		}
   213	
   214		return out, nil
   215	}
   216	
   217	// ReportOutput is the output of the Report verb.
   218	type ReportOutput struct {
   219		FirstContact []Report
   220		Updated      []Subject
   221	}
   222	
   223	// Report lands discrete testimony as HELD. Unknown subjects create new
   224	// holdings; known subjects are overwritten. Dedupes first, last wins,
   225	// survivor at last occurrence's position. Validates in order: nil → observer
   226	// → channel → subjects. All validation before any mutation (R5).
   227	func (i *Intel) Report(in *ReportInput) (*ReportOutput, error) {
   228		if in == nil {
   229			return nil, fmt.Errorf("report: %w", ErrNilInput)
   230		}
   231	
   232		if in.Observer == "" {
   233			return nil, fmt.Errorf("report: %w", ErrNoObserver)
   234		}
   235	
   236		if in.Channel == "" {
   237			return nil, fmt.Errorf("report: %w", ErrNoChannel)
   238		}
   239	
   240		for _, report := range in.Reports {
   241			if report.Subject == "" {
   242				return nil, fmt.Errorf("report: %w", ErrNoSubject)
   243			}
   244		}
   245	
   246		// Dedupe: last wins, survivor at last occurrence's position
   247		deduped := dedupeReports(in.Reports)
   248	
   249		out := &ReportOutput{
   250			FirstContact: []Report{},
   251			Updated:      []Subject{},
   252		}
   253	
   254		// No testimony means no mutation (R9 unreachable state guard)
   255		if len(deduped) == 0 {
   256			return out, nil
   257		}
   258	
   259		// Ensure observer map exists (only after confirming work to do)
   260		if _, exists := i.holdings[in.Observer]; !exists {
   261			i.holdings[in.Observer] = make(map[Subject]*holding)
   262		}
   263	
   264		// Process each deduplicated report
   265		for _, report := range deduped {
   266			// Make two independent copies: one for storage, one for FirstContact (copy-out R4)
   267			storageCopy := make([]byte, len(report.Payload))
   268			copy(storageCopy, report.Payload)
   269	
   270			if _, exists := i.holdings[in.Observer][report.Subject]; !exists {
   271				// New subject: create holding and add to FirstContact with independent copy
   272				firstContactCopy := make([]byte, len(report.Payload))
   273				copy(firstContactCopy, report.Payload)
   274				i.holdings[in.Observer][report.Subject] = &holding{
   275					payload:    storageCopy,
   276					channel:    in.Channel,
   277					at:         in.At,
   278					currentVia: make(map[Channel]struct{}),
   279				}
   280				out.FirstContact = append(out.FirstContact, Report{Subject: report.Subject, Payload: firstContactCopy})
   281			} else {
   282				// Known subject: overwrite payload, channel, at; leave currentVia untouched
   283				h := i.holdings[in.Observer][report.Subject]
   284				h.payload = storageCopy
   285				h.channel = in.Channel
   286				h.at = in.At
   287				out.Updated = append(out.Updated, report.Subject)
   288			}
   289		}
   290	
   291		return out, nil
   292	}
   293	
   294	// HeldByInput is the input to the HeldBy query.
   295	type HeldByInput struct {
   296		Observer core.EntityID
   297	}
   298	
   299	// HeldBy returns all holdings for an observer, sorted by Subject,
   300	// with statuses derived and payloads deep-copied. Unknown observer
   301	// returns empty slice, nil error.
   302	func (i *Intel) HeldBy(in *HeldByInput) ([]Holding, error) {
   303		if in == nil {
   304			return nil, fmt.Errorf("held by: %w", ErrNilInput)
   305		}
   306	
   307		if in.Observer == "" {
   308			return nil, fmt.Errorf("held by: %w", ErrNoObserver)
   309		}
   310	
   311		observerHoldings, exists := i.holdings[in.Observer]
   312		if !exists {
   313			return []Holding{}, nil
   314		}
   315	
   316		// Collect and convert holdings to exported type
   317		results := make([]Holding, 0, len(observerHoldings))
   318		for subject, h := range observerHoldings {
   319			results = append(results, h.toHolding(subject))
   320		}
   321	
   322		// Sort by Subject (deterministic order)
   323		slices.SortFunc(results, func(a, b Holding) int {
   324			if a.Subject < b.Subject {
   325				return -1
   326			}
   327			if a.Subject > b.Subject {
   328				return 1
   329			}
   330			return 0
   331		})
   332	
   333		return results, nil
   334	}
   335	
   336	// OnInput is the input to the On query.
   337	type OnInput struct {
   338		Observer core.EntityID
   339		Subject  Subject
   340	}
   341	
   342	// On returns a single holding for an observer and subject.
   343	// Returns ErrNotHeld if not held. Payload is deep-copied.
   344	func (i *Intel) On(in *OnInput) (Holding, error) {
   345		if in == nil {
   346			return Holding{}, fmt.Errorf("on: %w", ErrNilInput)
   347		}
   348	
   349		if in.Observer == "" {
   350			return Holding{}, fmt.Errorf("on: %w", ErrNoObserver)
   351		}
   352	
   353		if in.Subject == "" {
   354			return Holding{}, fmt.Errorf("on: %w", ErrNoSubject)
   355		}
   356	
   357		observerHoldings, exists := i.holdings[in.Observer]
   358		if !exists {
   359			return Holding{}, fmt.Errorf("on: %w", ErrNotHeld)
   360		}
   361	
   362		h, exists := observerHoldings[in.Subject]
   363		if !exists {
   364			return Holding{}, fmt.Errorf("on: %w", ErrNotHeld)
   365		}
   366	
   367		return h.toHolding(in.Subject), nil
   368	}
   369	
   370	// dedupeReports deduplicates reports, last wins, survivor at last
   371	// occurrence's position.
   372	func dedupeReports(reports []Report) []Report {
   373		// Track last occurrence of each subject
   374		lastOccurrence := make(map[Subject]int)
   375		for i, report := range reports {
   376			lastOccurrence[report.Subject] = i
   377		}
   378	
