    11	)
    12	
    13	// Data is the persistent representation of Intel state.
    14	// Holdings maps observer ID → (subject → holding data).
    15	type Data struct {
    16		Holdings map[core.EntityID]map[Subject]HoldingData `json:"holdings,omitempty"`
    17	}
    18	
    19	// HoldingData is the persistent representation of a single holding.
    20	// Payload is the opaque testimony. Channel and At are provenance.
    21	// CurrentVia lists channels currently sustaining this holding.
    22	// All fields are omitempty: nil payload marshals to omitted field,
    23	// and empty CurrentVia marshals to omitted (since it's never an empty non-nil slice).
    24	type HoldingData struct {
    25		Payload    []byte    `json:"payload,omitempty"`
    26		Channel    Channel   `json:"channel,omitempty"`
    27		At         uint64    `json:"at,omitempty"`
    28		CurrentVia []Channel `json:"current_via,omitempty"`
    29	}
    30	
    31	// ToData returns a persistent snapshot of this Intel.
    32	// Returns zero Data (nil Holdings map, not empty non-nil) if Intel is empty (R8 idle convention).
    33	// All payloads and slices are deep-copied; mutating the returned Data
    34	// will not affect this Intel.
    35	func (i *Intel) ToData() Data {
    36		if len(i.holdings) == 0 {
    37			// Idle convention: return zero value with nil map, not empty map
    38			return Data{}
    39		}
    40	
    41		// Copy holdings map
    42		result := Data{
    43			Holdings: make(map[core.EntityID]map[Subject]HoldingData),
    44		}
    45	
    46		for obs, subjects := range i.holdings {
    47			subjectMap := make(map[Subject]HoldingData)
    48			for subj, h := range subjects {
    49				// Deep-copy payload (only when not nil)
    50				var payloadCopy []byte
    51				if h.payload != nil {
    52					payloadCopy = make([]byte, len(h.payload))
    53					copy(payloadCopy, h.payload)
    54				}
    55	
    56				// Copy CurrentVia slice
    57				var currentViaCopy []Channel
    58				if len(h.currentVia) > 0 {
    59					currentViaCopy = make([]Channel, len(h.currentVia))
    60					// Extract channels from map in sorted order for determinism
    61					var channels []Channel
    62					for ch := range h.currentVia {
    63						channels = append(channels, ch)
    64					}
    65					slices.SortFunc(channels, func(a, b Channel) int {
    66						if a < b {
    67							return -1
    68						}
    69						if a > b {
    70							return 1
    71						}
    72						return 0
    73					})
    74					copy(currentViaCopy, channels)
    75				}
    76	
    77				subjectMap[subj] = HoldingData{
    78					Payload:    payloadCopy,
    79					Channel:    h.channel,
    80					At:         h.at,
    81					CurrentVia: currentViaCopy,
    82				}
    83			}
    84			result.Holdings[obs] = subjectMap
    85		}
    86	
    87		return result
    88	}
    89	
    90	// LoadIntel reconstructs an Intel from persistent data.
    91	// Returns (*Intel, error). On error, returns nil Intel and error wrapping ErrInvalidData.
    92	// Validates every holding: within a single holding the checks run in a fixed
    93	// order (observer key, nil/empty inner map, subject key, channel, CurrentVia
    94	// including empty-channel and duplicate detection), but observers and subjects
    95	// are visited in Go map order — which defect of a multi-defect Data is hit
    96	// first is NOT deterministic. That is unobservable by design: every rejection
    97	// is the same wrapped ErrInvalidData with no defect detail, and no partial
    98	// state is constructed (R5). All validation completes before any construction.
    99	// Payload nil is legal (see HoldingData doc).
   100	// Deep-copies all data: mutating the caller's Data after LoadIntel will not
   101	// affect the loaded Intel (R4).
   102	func LoadIntel(data Data) (*Intel, error) {
   103		// R5: validate everything first, then mutate
   104		if data.Holdings != nil {
   105			// Validate all keys and fields
   106			for obs, subjectMap := range data.Holdings {
   107				// Empty observer key is rejected
   108				if obs == "" {
   109					return nil, fmt.Errorf("load intel: %w", ErrInvalidData)
   110				}
   111	
   112				// Nil inner map is rejected
   113				if subjectMap == nil {
   114					return nil, fmt.Errorf("load intel: %w", ErrInvalidData)
   115				}
   116	
   117				// Empty (non-nil) inner map is rejected (unreachable state)
   118				if len(subjectMap) == 0 {
   119					return nil, fmt.Errorf("load intel: %w", ErrInvalidData)
   120				}
   121	
   122				for subj, hd := range subjectMap {
   123					// Empty subject key is rejected
   124					if subj == "" {
   125						return nil, fmt.Errorf("load intel: %w", ErrInvalidData)
   126					}
   127	
   128					// Empty holding Channel is rejected
   129					if hd.Channel == "" {
   130						return nil, fmt.Errorf("load intel: %w", ErrInvalidData)
   131					}
   132	
   133					// Validate CurrentVia: no empty channels, no duplicates
   134					seen := make(map[Channel]struct{})
   135					for _, ch := range hd.CurrentVia {
   136						if ch == "" {
   137							return nil, fmt.Errorf("load intel: %w", ErrInvalidData)
   138						}
   139						if _, dup := seen[ch]; dup {
   140							return nil, fmt.Errorf("load intel: %w", ErrInvalidData)
   141						}
   142						seen[ch] = struct{}{}
   143					}
   144				}
   145			}
   146		}
   147	
   148		// All validated; now reconstruct the Intel
   149		intel := &Intel{
   150			holdings: make(map[core.EntityID]map[Subject]*holding),
   151		}
   152	
   153		if data.Holdings != nil {
   154			for obs, subjectMap := range data.Holdings {
   155				intel.holdings[obs] = make(map[Subject]*holding)
   156				for subj, hd := range subjectMap {
   157					// Deep-copy payload (nil payloads remain nil; empty payloads are copied)
   158					var payloadCopy []byte
   159					if hd.Payload != nil {
   160						payloadCopy = make([]byte, len(hd.Payload))
   161						copy(payloadCopy, hd.Payload)
   162					}
   163	
   164					// Convert CurrentVia slice to internal set
   165					currentVia := make(map[Channel]struct{})
   166					for _, ch := range hd.CurrentVia {
   167						currentVia[ch] = struct{}{}
   168					}
   169	
   170					intel.holdings[obs][subj] = &holding{
   171						payload:    payloadCopy,
   172						channel:    hd.Channel,
   173						at:         hd.At,
   174						currentVia: currentVia,
   175					}
   176				}
   177			}
   178		}
   179	
   180		return intel, nil
   181	}
