     1	// Copyright (C) 2026 Kirk Diggler
     2	// SPDX-License-Identifier: GPL-3.0-or-later
     3	
     4	package intel
     5	
     6	import (
     7		"fmt"
     8		"slices"
     9	
    10		"github.com/KirkDiggler/rpg-toolkit/core"
    11	)
    12	
    13	// Channel identifies a source of testimony (hearing, sight, smell, etc).
    14	// Sight is the one predeclared channel; vocabulary is open — physical
    15	// channels get physics from the stage, supernatural from rulebooks;
    16	// intel treats all identically.
    17	type Channel string
    18	
    19	// Sight is the predeclared visual channel.
    20	const Sight Channel = "sight"
    21	
    22	// Subject is an opaque, caller-chosen identification within an
    23	// observer's fidelity: a place key, an entity ID, a believed identity.
    24	// Choosing subjects is part of the testimony.
    25	type Subject string
    26	
    27	// Report is one piece of testimony: a subject and an opaque payload.
    28	// Payload is empty legal; nil and empty are the same legal empty payload.
    29	type Report struct {
    30		Subject Subject
    31		Payload []byte
    32	}
    33	
    34	// Status identifies whether a holding is Current or Held.
    35	// Status is derived, never stored: Current iff any channel sustains.
    36	type Status string
    37	
    38	const (
    39		// Current indicates the subject is actively sustained by at least one channel.
    40		Current Status = "current"
    41		// Held indicates the subject is known but not actively sustained (a ghost).
    42		Held Status = "held"
    43	)
    44	
    45	// Holding is the read-side value: a subject, payload, channel provenance,
    46	// timestamp, active channels (CurrentVia), and derived status. Channel and
    47	// At are provenance of the latest accepted testimony. Status is derived
    48	// (Current iff CurrentVia is non-empty).
    49	type Holding struct {
    50		Subject    Subject
    51		Payload    []byte
    52		Channel    Channel
    53		At         uint64
    54		CurrentVia []Channel
    55		Status     Status
    56	}
    57	
    58	// Intel is the container for all observers' intel holdings.
    59	// Not safe for concurrent use. Zero value not usable; construct via
    60	// NewIntel or LoadIntel.
    61	type Intel struct {
    62		holdings map[core.EntityID]map[Subject]*holding
    63	}
    64	
    65	// internal holding struct stores the mutable state.
    66	type holding struct {
    67		payload    []byte
    68		channel    Channel
    69		at         uint64
    70		currentVia map[Channel]struct{}
    71	}
    72	
    73	// NewIntel creates a new Intel container.
    74	func NewIntel() (*Intel, error) {
    75		return &Intel{
    76			holdings: make(map[core.EntityID]map[Subject]*holding),
    77		}, nil
    78	}
    79	
    80	// SurveilInput carries a complete percept for this observer+channel.
    81	type SurveilInput struct {
    82		Observer core.EntityID
    83		Channel  Channel
    84		Percept  []Report
    85		At       uint64
    86	}
    87	
    88	// SurveilOutput reports the deltas Surveil caused.
    89	type SurveilOutput struct {
    90		FirstContact []Report
    91		Refreshed    []Subject
    92		Faded        []Subject
    93	}
    94	
    95	// ReportInput is the input to the Report verb.
    96	type ReportInput struct {
    97		Observer core.EntityID
    98		Channel  Channel
    99		Reports  []Report
   100		At       uint64
   101	}
   102	
   103	// Surveil records a complete percept for an observer+channel. Fading is
   104	// derived: every subject previously current via this channel but absent from
   105	// Percept has that channel removed from CurrentVia. If CurrentVia becomes
   106	// empty, the subject fades (still held — the ghost goblin). An empty Percept
   107	// is legal (seeing nothing: fades everything this channel sustained). Errors:
   108	// ErrNilInput, ErrNoObserver, ErrNoChannel, ErrNoSubject — validation first,
   109	// all before any mutation (R5).
   110	func (i *Intel) Surveil(in *SurveilInput) (*SurveilOutput, error) {
   111		if in == nil {
   112			return nil, fmt.Errorf("surveil: %w", ErrNilInput)
   113		}
   114	
   115		if in.Observer == "" {
   116			return nil, fmt.Errorf("surveil: %w", ErrNoObserver)
   117		}
   118	
   119		if in.Channel == "" {
   120			return nil, fmt.Errorf("surveil: %w", ErrNoChannel)
   121		}
   122	
   123		for _, report := range in.Percept {
   124			if report.Subject == "" {
   125				return nil, fmt.Errorf("surveil: %w", ErrNoSubject)
   126			}
   127		}
   128	
   129		// Dedupe percept (same as Report): last entry wins, survivor at last position
   130		deduped := dedupeReports(in.Percept)
   131		dedupeSubjectSet := make(map[Subject]struct{}, len(deduped))
   132		for _, r := range deduped {
   133			dedupeSubjectSet[r.Subject] = struct{}{}
   134		}
   135	
   136		out := &SurveilOutput{}
   137	
   138		// Phantom-observer guard: lazy observer-map creation only after validation
   139		// and only if the deduped percept is non-empty OR observer already exists
   140		if len(deduped) == 0 && i.holdings[in.Observer] == nil {
   141			// Empty percept for unknown observer must not create state
   142			return out, nil
   143		}
   144	
   145		// Ensure observer exists if we're about to do something
   146		if i.holdings[in.Observer] == nil {
   147			i.holdings[in.Observer] = make(map[Subject]*holding)
   148		}
   149	
   150		// FADE PASS: from pre-mutation state, remove channel from holdings
   151		// whose currentVia contains this channel AND subject absent from deduped percept
   152		var fadedSubjects []Subject
   153		for subj, h := range i.holdings[in.Observer] {
   154			// Check if this subject was sustained by this channel
   155			if _, ok := h.currentVia[in.Channel]; ok {
   156				// Check if it's absent from the deduped percept
   157				if _, present := dedupeSubjectSet[subj]; !present {
   158					// Remove the channel
   159					delete(h.currentVia, in.Channel)
   160					// If currentVia is now empty, collect for Faded
   161					if len(h.currentVia) == 0 {
   162						fadedSubjects = append(fadedSubjects, subj)
   163					}
   164				}
   165			}
   166		}
   167	
   168		// Sort Faded by Subject for deterministic transcripts; only assign if non-empty
   169		if len(fadedSubjects) > 0 {
   170			slices.SortFunc(fadedSubjects, func(a, b Subject) int {
   171				if a < b {
   172					return -1
   173				}
   174				if a > b {
   175					return 1
   176				}
