   223	// Report lands discrete testimony as HELD. Unknown subjects create new
   224	// holdings; known subjects are overwritten. Dedupes first, last wins,
   225	// survivor at last occurrence's position. Validates in order: nil → observer
   226	// → channel → subjects. All validation before any mutation (R5).
   227	func (i *Intel) Report(in *ReportInput) (*ReportOutput, error) {
   228		if in == nil {
   229			return nil, fmt.Errorf("report: %w", ErrNilInput)
   230		}
   231	
   232		if in.Observer == "" {
   233			return nil, fmt.Errorf("report: %w", ErrNoObserver)
   234		}
   235	
   236		if in.Channel == "" {
   237			return nil, fmt.Errorf("report: %w", ErrNoChannel)
   238		}
   239	
   240		for _, report := range in.Reports {
   241			if report.Subject == "" {
   242				return nil, fmt.Errorf("report: %w", ErrNoSubject)
   243			}
   244		}
   245	
   246		// Dedupe: last wins, survivor at last occurrence's position
   247		deduped := dedupeReports(in.Reports)
   248	
   249		out := &ReportOutput{
   250			FirstContact: []Report{},
   251			Updated:      []Subject{},
   252		}
   253	
   254		// No testimony means no mutation (R9 unreachable state guard)
   255		if len(deduped) == 0 {
   256			return out, nil
   257		}
   258	
   259		// Ensure observer map exists (only after confirming work to do)
   260		if _, exists := i.holdings[in.Observer]; !exists {
   261			i.holdings[in.Observer] = make(map[Subject]*holding)
   262		}
   263	
   264		// Process each deduplicated report
   265		for _, report := range deduped {
   266			// Make two independent copies: one for storage, one for FirstContact (copy-out R4)
   267			storageCopy := make([]byte, len(report.Payload))
   268			copy(storageCopy, report.Payload)
   269	
   270			if _, exists := i.holdings[in.Observer][report.Subject]; !exists {
   271				// New subject: create holding and add to FirstContact with independent copy
   272				firstContactCopy := make([]byte, len(report.Payload))
   273				copy(firstContactCopy, report.Payload)
   274				i.holdings[in.Observer][report.Subject] = &holding{
   275					payload:    storageCopy,
   276					channel:    in.Channel,
   277					at:         in.At,
   278					currentVia: make(map[Channel]struct{}),
   279				}
   280				out.FirstContact = append(out.FirstContact, Report{Subject: report.Subject, Payload: firstContactCopy})
   281			} else {
   282				// Known subject: overwrite payload, channel, at; leave currentVia untouched
   283				h := i.holdings[in.Observer][report.Subject]
   284				h.payload = storageCopy
   285				h.channel = in.Channel
   286				h.at = in.At
   287				out.Updated = append(out.Updated, report.Subject)
   288			}
   289		}
   290	
   291		return out, nil
   292	}
