    13	// Data is the persistent representation of Intel state.
    14	// Holdings maps observer ID → (subject → holding data).
    15	type Data struct {
    16		Holdings map[core.EntityID]map[Subject]HoldingData `json:"holdings,omitempty"`
    17	}
    18	
    19	// HoldingData is the persistent representation of a single holding.
    20	// Payload is the opaque testimony. Channel and At are provenance.
    21	// CurrentVia lists channels currently sustaining this holding.
    22	// All fields are omitempty: nil payload marshals to omitted field,
    23	// and empty CurrentVia marshals to omitted (since it's never an empty non-nil slice).
    24	type HoldingData struct {
    25		Payload    []byte    `json:"payload,omitempty"`
    26		Channel    Channel   `json:"channel,omitempty"`
    27		At         uint64    `json:"at,omitempty"`
    28		CurrentVia []Channel `json:"current_via,omitempty"`
    29	}
    30	
    31	// ToData returns a persistent snapshot of this Intel.
    32	// Returns zero Data (nil Holdings map, not empty non-nil) if Intel is empty (R8 idle convention).
    33	// All payloads and slices are deep-copied; mutating the returned Data
    34	// will not affect this Intel.
    35	func (i *Intel) ToData() Data {
    36		if len(i.holdings) == 0 {
    37			// Idle convention: return zero value with nil map, not empty map
    38			return Data{}
    39		}
    40	
    41		// Copy holdings map
    42		result := Data{
    43			Holdings: make(map[core.EntityID]map[Subject]HoldingData),
    44		}
    45	
    46		for obs, subjects := range i.holdings {
    47			subjectMap := make(map[Subject]HoldingData)
    48			for subj, h := range subjects {
    49				// Deep-copy payload (only when not nil)
    50				var payloadCopy []byte
    51				if h.payload != nil {
    52					payloadCopy = make([]byte, len(h.payload))
    53					copy(payloadCopy, h.payload)
    54				}
    55	
    56				// Copy CurrentVia slice
    57				var currentViaCopy []Channel
    58				if len(h.currentVia) > 0 {
    59					currentViaCopy = make([]Channel, len(h.currentVia))
    60					// Extract channels from map in sorted order for determinism
    61					var channels []Channel
    62					for ch := range h.currentVia {
    63						channels = append(channels, ch)
    64					}
    65					slices.SortFunc(channels, func(a, b Channel) int {
    66						if a < b {
    67							return -1
    68						}
    69						if a > b {
    70							return 1
    71						}
    72						return 0
    73					})
    74					copy(currentViaCopy, channels)
    75				}
    76	
    77				subjectMap[subj] = HoldingData{
    78					Payload:    payloadCopy,
    79					Channel:    h.channel,
    80					At:         h.at,
    81					CurrentVia: currentViaCopy,
    82				}
    83			}
    84			result.Holdings[obs] = subjectMap
    85		}
    86	
    87		return result
    88	}
